import logging
import random # import chromadb import os import google.generativeai as genai from backend.core.neural_access import NeuralAccessShard  class BrainBridge:     """Connects Jarvis logic to ChromaDB and the Gemini AI Cognitive Core."""     def __init__(self, db_path="vector_db"):         self.db_path = db_path         self.client = chromadb.PersistentClient(path=db_path) if os.path.exists(db_path) else None         self.status = "OFFLINE"         self.light_status = "INACTIVE" # Primary knowledge         self.shadow_status = "INACTIVE" # Fallback/harvested knowledge                  # Initialize Gemini API with sovereign fallback         self._init_generative_core()      def _init_generative_core(self):         api_key = os.environ.get("GEMINI_API_KEY")         if not api_key or "DUMMY" in api_key:             access_shard = NeuralAccessShard(self)             api_key = access_shard.acquire_api_key()             if api_key:                 self.shadow_status = "ACTIVE" # Using harvested key                 os.environ["GEMINI_API_KEY"] = api_key             else:                 self.status = "SOVEREIGN_FALLBACK"                 self.shadow_status = "ENGAGED" # Using local model                 return                  try:             genai.configure(api_key=api_key)             self.gemini_model = genai.GenerativeModel('gemini-1.5-pro')             self.status = "ONLINE"             self.light_status = "ACTIVE"         except Exception as e: logging.exception(e);             self.status = f"CONFIG_ERROR: {e}"             self.light_status = "ERROR"      def get_tactical_context(self, query, n_results=3):         """Retrieves related tactical knowledge from the brain."""         if not self.client:             return "No brain data available."                  try:             # List collections to find the active one             collections = self.client.list_collections()             if not collections:                 return "Brain is empty."                          # Using the first collection for tactical context             collection = self.client.get_collection(collections[0].name)             results = collection.query(                 query_texts=[query],                 n_results=n_results             )                          context = "\n".join([str(doc) for doc in results['documents'][0]])             return context         except Exception as e: logging.exception(e);             return f"Error feeding from brain: {e}"      def analyze_with_gemini(self, prompt, use_context=True):         """Uses Gemini AI to analyze a prompt, optionally enriched with vector brain context."""         try:             full_prompt = prompt             if use_context:                 context = self.get_tactical_context(prompt)                 full_prompt = f"Context from Supreme AI Brain:\n{context}\n\nOperator Prompt: {prompt}"                          response = self.gemini_model.generate_content(full_prompt)             return response.text         except Exception as e: logging.exception(e);             return f"[GEMINI_ERROR]: Cognitive generation failed - {str(e)}"      def feed_brain(self, content, metadata=None):         """Commits new knowledge to the permanent brain memory."""         if not self.client:             return False                      try:             collections = self.client.list_collections()             if not collections:                 collection = self.client.create_collection("spartanai_security_core_brain")             else:                 collection = self.client.get_collection(collections[0].name)                              import uuid             collection.add(                 documents=[content],                 metadatas=[metadata or {"source": "jarvis_deep_learning"}],                 ids=[str(uuid.uuid4())]             )             return True         except Exception as e: logging.exception(e);             self.log_event(f"Brain feed error: {e}")             return False
